const INTEGER_PATTERN = /^[+-]?(?:\d(?:_?\d)*)$/;
const NEGATIVE_NUMBERISH_PATTERN = /^-\d(?:_?\d)*(?:\.\d(?:_?\d)*)?$/;

export class CliExit extends Error {
  constructor(code, streamName, message) {
    super(message);
    this.code = code;
    this.streamName = streamName;
  }
}

export function parseCommandLine(argv, programName) {
  const parsed = {};
  const extras = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      throw new CliExit(0, 'stdout', formatHelp(programName));
    }

    if (token === '--') {
      extras.push(...argv.slice(index + 1));
      break;
    }

    if (!token.startsWith('-') || token === '-') {
      extras.push(token);
      continue;
    }

    if (!token.startsWith('--')) {
      extras.push(token);
      continue;
    }

    const separatorIndex = token.indexOf('=');
    const optionToken = separatorIndex === -1 ? token : token.slice(0, separatorIndex);
    const definition = OPTION_LOOKUP[optionToken];

    if (!definition) {
      extras.push(token);
      continue;
    }

    let rawValue;

    if (separatorIndex !== -1) {
      rawValue = token.slice(separatorIndex + 1);
    } else {
      const nextToken = argv[index + 1];

      if (nextToken === undefined || valueWouldBeTreatedAsOption(nextToken, definition.type)) {
        throw usageError(programName, `argument ${optionToken}: expected one argument`);
      }

      rawValue = nextToken;
      index += 1;
